<template><div class="app-container ps-page"><h2>知识空间</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><div class="ps-toolbar"><el-button v-hasPermi="['paismart:space:edit']" type="primary" @click="edit()">新增空间</el-button><el-button :loading="loading" @click="load()">刷新</el-button></div><el-table :data="rows" v-loading="loading" row-key="id"><el-table-column prop="name" label="空间名称" min-width="200"/><el-table-column label="上级空间" min-width="180"><template #default="{row}">{{rows.find(s=>String(s.id)===String(row.parentId))?.name||'根空间'}}</template></el-table-column><el-table-column prop="description" label="说明" min-width="250"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button v-hasPermi="['paismart:space:edit']" link :disabled="row.canManage===false||row.type==='PERSONAL'" @click="edit(row)">编辑</el-button><el-button v-hasPermi="['paismart:space:list']" link :disabled="row.type==='PERSONAL'" @click="primary(row)">设为主空间</el-button><el-button v-hasPermi="['paismart:space:edit']" link type="danger" :disabled="row.canManage===false||row.type==='PERSONAL'" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="open" :title="form.id?'编辑空间':'新增空间'" width="560px"><el-form label-width="90px"><el-form-item label="名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="上级空间"><el-select v-model="form.parentId" clearable><el-option v-for="row in rows.filter(s=>s.id!==form.id&&s.type!=='PERSONAL')" :key="row.id" :label="row.name" :value="row.id"/></el-select></el-form-item><el-form-item label="非管理人员单文件上限(MiB)"><el-input-number v-model="maxMiB" :min="0" :precision="2"/><span class="ps-muted">0 为不单独限制，仍受全局上传政策约束</span></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" maxlength="5000"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { deleteSpace, listSpaces, saveSpace, setPrimarySpace } from '@/api/paismart/spaces'
import type { Space } from '@/types/paismart'
import { errorText,usePage } from '../composables/usePage'
import '../common.css'
const {rows,loading,error,load}=usePage((_q,signal)=>listSpaces(signal)),pageError=ref(''),formError=ref(''),open=ref(false),saving=ref(false),form=ref<Partial<Space>>({}),maxMiB=ref(0)
function edit(row?:Space){form.value=row?{...row}:{name:'',description:''};maxMiB.value=(row?.uploadMaxSizeBytes||0)/1024/1024;formError.value='';open.value=true}
async function save(){if(!form.value.name?.trim()){formError.value='请填写空间名称';return}saving.value=true;formError.value='';try{await saveSpace({...form.value,type:form.value.type||'ORGANIZATION',uploadLimit:form.value.uploadLimit??-1,uploadMaxSizeBytes:maxMiB.value>0?Math.round(maxMiB.value*1024*1024):null});open.value=false;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function primary(row:Space){try{await setPrimarySpace(row.id);ElMessage.success('主空间已更新')}catch(e){pageError.value=errorText(e)}}
async function remove(row:Space){try{await ElMessageBox.confirm(`删除空间「${row.name}」前，服务端将核对成员、子空间与文档归属。`, '删除空间',{type:'warning'});await deleteSpace(row);await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}}
onMounted(()=>void load())
</script>
